package com.securebank.model;

import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;

/**
 * SecureBank: Complete Banking Automation System
 * File: SuspiciousActivityAlert.java
 *
 * Represents an automated fraud detection alert generated by the
 * Suspicious Activity Monitoring engine.
 */
public class SuspiciousActivityAlert {

    private long alertId;
    private LocalDateTime timestamp;
    private Integer userId;
    private Integer accountNumber;
    private String ruleTriggered;
    private String severity; // LOW, MEDIUM, HIGH, CRITICAL
    private String evidence;
    private String status; // OPEN, INVESTIGATING, RESOLVED, DISMISSED

    private int riskScore;
    private String reviewDecision; // RESOLVED_SAFE, CONFIRMED_FRAUD, DISMISSED
    private String reviewerUsername;
    private LocalDateTime reviewedAt;

    private static final DateTimeFormatter TS_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss");

    public SuspiciousActivityAlert() {
        this.timestamp = LocalDateTime.now();
        this.status = "OPEN";
        this.severity = "MEDIUM";
        this.riskScore = 50;
    }

    public SuspiciousActivityAlert(
        long alertId,
        LocalDateTime timestamp,
        Integer userId,
        Integer accountNumber,
        String ruleTriggered,
        String severity,
        String evidence,
        String status
    ) {
        this(alertId, timestamp, userId, accountNumber, ruleTriggered, severity, evidence, status, 50, null, null, null);
    }

    public SuspiciousActivityAlert(
        long alertId,
        LocalDateTime timestamp,
        Integer userId,
        Integer accountNumber,
        String ruleTriggered,
        String severity,
        String evidence,
        String status,
        int riskScore,
        String reviewDecision,
        String reviewerUsername,
        LocalDateTime reviewedAt
    ) {
        this.alertId = alertId;
        this.timestamp = timestamp != null ? timestamp : LocalDateTime.now();
        this.userId = userId;
        this.accountNumber = accountNumber;
        this.ruleTriggered = ruleTriggered;
        this.severity = severity != null ? severity : "MEDIUM";
        this.evidence = evidence;
        this.status = status != null ? status : "OPEN";
        this.riskScore = riskScore;
        this.reviewDecision = reviewDecision;
        this.reviewerUsername = reviewerUsername;
        this.reviewedAt = reviewedAt;
    }

    public int getRiskScore() {
        return riskScore;
    }

    public void setRiskScore(int riskScore) {
        this.riskScore = riskScore;
    }

    public String getReviewDecision() {
        return reviewDecision;
    }

    public void setReviewDecision(String reviewDecision) {
        this.reviewDecision = reviewDecision;
    }

    public String getReviewerUsername() {
        return reviewerUsername;
    }

    public void setReviewerUsername(String reviewerUsername) {
        this.reviewerUsername = reviewerUsername;
    }

    public LocalDateTime getReviewedAt() {
        return reviewedAt;
    }

    public void setReviewedAt(LocalDateTime reviewedAt) {
        this.reviewedAt = reviewedAt;
    }

    public long getAlertId() {
        return alertId;
    }

    public void setAlertId(long alertId) {
        this.alertId = alertId;
    }

    public LocalDateTime getTimestamp() {
        return timestamp;
    }

    public void setTimestamp(LocalDateTime timestamp) {
        this.timestamp = timestamp;
    }

    public Integer getUserId() {
        return userId;
    }

    public void setUserId(Integer userId) {
        this.userId = userId;
    }

    public Integer getAccountNumber() {
        return accountNumber;
    }

    public void setAccountNumber(Integer accountNumber) {
        this.accountNumber = accountNumber;
    }

    public String getRuleTriggered() {
        return ruleTriggered;
    }

    public void setRuleTriggered(String ruleTriggered) {
        this.ruleTriggered = ruleTriggered;
    }

    public String getSeverity() {
        return severity;
    }

    public void setSeverity(String severity) {
        this.severity = severity;
    }

    public String getEvidence() {
        return evidence;
    }

    public void setEvidence(String evidence) {
        this.evidence = evidence;
    }

    public String getStatus() {
        return status;
    }

    public void setStatus(String status) {
        this.status = status;
    }

    public String getFormattedTimestamp() {
        return timestamp != null ? timestamp.format(TS_FMT) : "";
    }
}
